import pytest

from tarjan import scc, condense


def brute_force_scc(adj):
    """Reachability-based reference SCC computation."""
    nodes = list(adj)

    def reach(u):
        seen = {u}
        work = [u]
        while work:
            x = work.pop()
            for y in adj.get(x, []):
                if y not in seen:
                    seen.add(y)
                    work.append(y)
        return seen

    r = {u: reach(u) for u in nodes}
    assigned = set()
    comps = []
    for u in nodes:
        if u in assigned:
            continue
        comp = [v for v in nodes if v in r[u] and u in r[v]]
        comp.sort()
        comps.append(comp)
        assigned.update(comp)
    return sorted(comps)


def canon(comps):
    return sorted(sorted(c) for c in comps)


def test_classic_8_node_example():
    # Classic example: 3 SCCs among 8 nodes.
    adj = {
        0: [1],
        1: [2],
        2: [0, 3],
        3: [4],
        4: [5, 7],
        5: [6],
        6: [4],
        7: [],
    }
    comps = scc(adj)
    assert canon(comps) == [[0, 1, 2], [3], [4, 5, 6], [7]]
    assert sum(len(c) for c in comps) == 8
    assert all(canon(comps).count([n]) or n in (0, 1, 2, 4, 5, 6) for n in range(8))


def test_pure_cycle():
    adj = {i: [(i + 1) % 10] for i in range(10)}
    comps = scc(adj)
    assert canon(comps) == [list(range(10))]


def test_dag_singletons():
    adj = {
        0: [1, 2],
        1: [3],
        2: [3],
        3: [],
    }
    comps = scc(adj)
    assert canon(comps) == [[0], [1], [2], [3]]
    # Reverse topological order: successors come after predecessors.
    pos = {n: i for i, comp in enumerate(comps) for n in comp}
    for u, succs in adj.items():
        for v in succs:
            assert pos[u] < pos[v]


def test_self_loops():
    adj = {0: [0], 1: [1, 2], 2: []}
    comps = scc(adj)
    assert canon(comps) == [[0], [1, 2]]


def test_large_path_50k():
    n = 50_000
    adj = {i: [i + 1] for i in range(n - 1)}
    adj[n - 1] = []
    comps = scc(adj)
    assert len(comps) == n
    assert all(len(c) == 1 for c in comps)


def test_random_vs_brute_force():
    rng = random.Random(12345)
    for _ in range(200):
        n = 12
        p = rng.random() * 0.6
        adj = {u: [] for u in range(n)}
        for u in range(n):
            for v in range(n):
                if rng.random() < p:
                    adj[u].append(v)
        got = canon(scc(adj))
        expected = canon(brute_force_scc(adj))
        assert got == expected


def test_condense_is_dag_and_matches_components():
    adj = {
        0: [1],
        1: [2],
        2: [0, 3],
        3: [4],
        4: [5, 7],
        5: [6],
        6: [4, 7],
        7: [3],
    }
    dag = condense(adj)
    # Every original node maps to exactly one condensed node.
    assert len(dag) == 4
    # No self-loops, acyclic (DFS finds no back edges).
    WHITE, GRAY, BLACK = 0, 1, 2
    color = {u: WHITE for u in dag}

    def dfs(u):
        color[u] = GRAY
        for v in dag[u]:
            assert color[v] != GRAY, "cycle in condensation"
            if color[v] == WHITE:
                dfs(v)
        color[u] = BLACK

    import sys
    sys.setrecursionlimit(10000)
    for u in dag:
        if color[u] == WHITE:
            dfs(u)

    for u, succs in dag.items():
        for v in succs:
            assert v != u

