def test_condense_edges_consistent():
    adj = {
        0: [1],
        1: [2],
        2: [0, 3],
        3: [4],
        4: [5, 7],
        5: [6],
        6: [4, 7],
        7: [3],
    }
    comps = scc(adj)
    dag = condense(adj)

    # Reconstruct which condensed node holds which original nodes by
    # counting members: total membership must equal number of nodes,
    # and the number of condensed nodes equals the number of components.
    assert len(dag) == len(comps) == 4

    # Condensation must be acyclic and have no self-loops.
    WHITE, GRAY, BLACK = 0, 1, 2
    color = dict.fromkeys(dag, WHITE)
    for start in dag:
        if color[start] != WHITE:
            continue
        stk = [(start, iter(dag[start]))]
        color[start] = GRAY
        while stk:
            u, it = stk[-1]
            advanced = False
            for v in it:
                assert color[v] != GRAY, "cycle in condensation"
                if color[v] == WHITE:
                    color[v] = GRAY
                    stk.append((v, iter(dag[v])))
                    advanced = True
                    break
            if not advanced:
                color[u] = BLACK
                stk.pop()

    # Edge counts: number of inter-component edges preserved.
    comp_of = {}
    for comp in comps:
        key = id(comp)  # placeholder; use sizes instead
    # Count inter-component edges directly from components.
    def find(node, groups):
        for g in groups:
            if node in g:
                return g
    groups = [frozenset(c) for c in comps]
    expected_pairs = set()
    for u, succs in adj.items():
        gu = find(u, groups)
        for v in succs:
            gv = find(v, groups)
            if gu is not gv:
                expected_pairs.add((groups.index(gu), groups.index(gv)))
    actual_edges = sum(len(succs) for succs in dag.values())
    assert actual_edges == len(expected_pairs)
